#include <map>
#include <memory>
#include <set>
#include <unordered_map>
struct UeContext { int id; std::set<int> sessionIds; };
struct PduSession { enum class State { Creating, Active, Releasing }; int ueId; int psi; State state = State::Creating; std::unordered_map<int, int> qosFlows; };
struct SessionStore { std::map<std::pair<int, int>, std::unique_ptr<PduSession>> sessions; };
PduSession* createSession(SessionStore& store, UeContext& ue, int psi) {
    auto key = std::make_pair(ue.id, psi);
    if (store.sessions.count(key)) return nullptr;
    auto session = std::make_unique<PduSession>();
    session->ueId = ue.id;
    session->psi = psi;
    auto* result = session.get();
    store.sessions.emplace(key, std::move(session));
    ue.sessionIds.insert(psi);
    return result;
}
void eraseSession(SessionStore& store, UeContext& ue, int psi) {
    auto it = store.sessions.find(std::make_pair(ue.id, psi));
    if (it == store.sessions.end()) return;
    ue.sessionIds.erase(psi);
    store.sessions.erase(it);
}
void onEstablishmentResult(SessionStore& store, UeContext& ue, int psi, bool accepted, const std::unordered_map<int, int>& flows) {
    auto it = store.sessions.find(std::make_pair(ue.id, psi));
    if (it == store.sessions.end()) return;
    if (!accepted) { eraseSession(store, ue, psi); return; }
    it->second->qosFlows = flows;
    it->second->state = PduSession::State::Active;
}
bool updateQosFlow(SessionStore& store, UeContext& ue, int psi, int qfi, int profile) {
    auto it = store.sessions.find(std::make_pair(ue.id, psi));
    if (it == store.sessions.end() || it->second->state != PduSession::State::Active) return false;
    it->second->qosFlows[qfi] = profile;
    return true;
}
bool beginRelease(SessionStore& store, UeContext& ue, int psi) {
    auto it = store.sessions.find(std::make_pair(ue.id, psi));
    if (it == store.sessions.end() || it->second->state != PduSession::State::Active) return false;
    it->second->state = PduSession::State::Releasing;
    return true;
}
bool completeRelease(SessionStore& store, UeContext& ue, int psi) {
    auto it = store.sessions.find(std::make_pair(ue.id, psi));
    if (it == store.sessions.end() || it->second->state != PduSession::State::Releasing) return false;
    eraseSession(store, ue, psi);
    return true;
}

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <unordered_map>
enum class RegistrationState { Deregistered, Pending, Registered, Deregistering };
struct UeContext {
    std::string supi;
    RegistrationState state = RegistrationState::Deregistered;
    std::optional<std::uint64_t> ranUeId;
};
struct AmfContextStore { std::unordered_map<std::string, std::unique_ptr<UeContext>> ues; };
UeContext& beginRegistration(AmfContextStore& amf, const std::string& supi) {
    auto it = amf.ues.find(supi);
    if (it == amf.ues.end()) {
        auto context = std::make_unique<UeContext>();
        context->supi = supi;
        it = amf.ues.emplace(supi, std::move(context)).first;
    }
    it->second->state = RegistrationState::Pending;
    return *it->second;
}
void attachRanUe(UeContext& ue, std::uint64_t ranUeId) { ue.ranUeId = ranUeId; }
bool acceptRegistration(AmfContextStore& amf, const std::string& supi) {
    auto it = amf.ues.find(supi);
    if (it == amf.ues.end() || !it->second->ranUeId) return false;
    it->second->state = RegistrationState::Registered;
    return true;
}
void detachRanUe(UeContext& ue, std::uint64_t ranUeId) {
    if (ue.ranUeId && *ue.ranUeId == ranUeId) ue.ranUeId.reset();
}
void beginDeregistration(UeContext& ue) {
    if (ue.state == RegistrationState::Registered) ue.state = RegistrationState::Deregistering;
}
void completeDeregistration(AmfContextStore& amf, const std::string& supi) {
    auto it = amf.ues.find(supi);
    if (it == amf.ues.end() || it->second->state != RegistrationState::Deregistering) return;
    it->second->ranUeId.reset();
    amf.ues.erase(it);
}

#include <cstdint>
#include <memory>
#include <unordered_map>
enum class PfcpSessionState { Installing, Active, Deleting };
struct PfcpSession {
    std::uint64_t localSeid;
    int peerNodeId;
    PfcpSessionState state = PfcpSessionState::Installing;
    bool hasUeAddress = false;
    std::uint32_t ueAddress = 0;
    std::unordered_map<int, int> pdrs;
};
struct UpfContext { std::unordered_map<std::uint64_t, std::unique_ptr<PfcpSession>> sessions; };
PfcpSession* createPfcpSession(UpfContext& upf, std::uint64_t localSeid, int peerNodeId, const std::unordered_map<int, int>& initialPdrs) {
    if (upf.sessions.count(localSeid)) return nullptr;
    auto session = std::make_unique<PfcpSession>();
    session->localSeid = localSeid;
    session->peerNodeId = peerNodeId;
    session->pdrs = initialPdrs;
    auto* result = session.get();
    upf.sessions.emplace(localSeid, std::move(session));
    return result;
}
void onEstablishmentResponse(UpfContext& upf, std::uint64_t localSeid, bool accepted, std::uint32_t assignedAddress) {
    auto it = upf.sessions.find(localSeid);
    if (it == upf.sessions.end()) return;
    if (!accepted) { upf.sessions.erase(it); return; }
    it->second->ueAddress = assignedAddress;
    it->second->hasUeAddress = true;
    it->second->state = PfcpSessionState::Active;
}
bool updatePdr(UpfContext& upf, std::uint64_t localSeid, int pdrId, int forwardingProfile) {
    auto it = upf.sessions.find(localSeid);
    if (it == upf.sessions.end() || it->second->state != PfcpSessionState::Active) return false;
    it->second->pdrs[pdrId] = forwardingProfile;
    return true;
}
bool requestDeletion(UpfContext& upf, std::uint64_t localSeid) {
    auto it = upf.sessions.find(localSeid);
    if (it == upf.sessions.end() || it->second->state != PfcpSessionState::Active) return false;
    it->second->state = PfcpSessionState::Deleting;
    return true;
}
void onDeletionResponse(UpfContext& upf, std::uint64_t localSeid, bool accepted) {
    auto it = upf.sessions.find(localSeid);
    if (it == upf.sessions.end() || it->second->state != PfcpSessionState::Deleting) return;
    if (accepted) upf.sessions.erase(it);
}
void removePeerSessions(UpfContext& upf, int peerNodeId) {
    for (auto it = upf.sessions.begin(); it != upf.sessions.end();) {
        if (it->second->peerNodeId == peerNodeId) it = upf.sessions.erase(it);
        else ++it;
    }
}
